"""
    Defines default styling of scatter graphs with some smoothing.
    Args:
        color:
        line_style:

    Returns: line_style dict parameters

    """
def set_line_style(color: Any, width: Any = 3, line_style: Any = "solid") -> object {
    style = `dict(color=color, width=width, dash=line_style);
    return style;
}

